'use strict';

function validText(value) {
  return typeof value === 'string' && value.length > 0;
}

function validateItem(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item) ||
      !validText(item.sku) || !validText(item.name) ||
      !Number.isInteger(item.quantity) || item.quantity < 0) {
    throw new TypeError('Invalid inventory item');
  }
}

function validateState(state) {
  if (!Array.isArray(state)) throw new TypeError('State must be an array');
  const seen = new Set();
  for (const item of state) {
    validateItem(item);
    if (seen.has(item.sku)) throw new TypeError('State contains duplicate SKUs');
    seen.add(item.sku);
  }
}

function requireSku(sku) {
  if (!validText(sku)) throw new TypeError('SKU must be a non-empty string');
}

function applyInventoryCommand(state, command) {
  validateState(state);
  if (!command || typeof command !== 'object' || Array.isArray(command) ||
      typeof command.type !== 'string') {
    throw new TypeError('Invalid command');
  }

  const result = state.map((item) => ({ ...item }));

  if (command.type === 'ADD') {
    validateItem(command.item);
    if (result.some((item) => item.sku === command.item.sku)) {
      throw new RangeError('Duplicate SKU');
    }
    result.push({ ...command.item });
    return result;
  }

  if (command.type === 'RESTOCK') {
    requireSku(command.sku);
    if (!Number.isInteger(command.amount) || command.amount === 0) {
      throw new TypeError('Amount must be a non-zero integer');
    }
    const index = result.findIndex((item) => item.sku === command.sku);
    if (index < 0) throw new RangeError('Unknown SKU');
    const quantity = result[index].quantity + command.amount;
    if (quantity < 0) throw new RangeError('Quantity cannot be negative');
    result[index].quantity = quantity;
    return result;
  }

  if (command.type === 'RENAME') {
    requireSku(command.sku);
    if (!validText(command.name)) throw new TypeError('Name must be non-empty');
    const index = result.findIndex((item) => item.sku === command.sku);
    if (index < 0) throw new RangeError('Unknown SKU');
    result[index].name = command.name;
    return result;
  }

  if (command.type === 'REMOVE') {
    requireSku(command.sku);
    const index = result.findIndex((item) => item.sku === command.sku);
    if (index < 0) throw new RangeError('Unknown SKU');
    result.splice(index, 1);
    return result;
  }

  throw new RangeError('Unknown command type');
}

function findInventoryItem(state, sku) {
  validateState(state);
  requireSku(sku);
  const item = state.find((entry) => entry.sku === sku);
  return item || null;
}

module.exports = { applyInventoryCommand, findInventoryItem };

