'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['applyInventoryCommand', 'findInventoryItem']);
const { applyInventoryCommand, findInventoryItem } = api;

const state = Object.freeze([
  Object.freeze({ sku: 'A', name: 'Apple', quantity: 2 }),
  Object.freeze({ sku: 'B', name: 'Banana', quantity: 5 })
]);

const addedItem = Object.freeze({ sku: 'C', name: 'Cherry', quantity: 0 });
const addCommand = Object.freeze({ type: 'ADD', item: addedItem });
const added = applyInventoryCommand(state, addCommand);
assert.deepEqual(added, [
  { sku: 'A', name: 'Apple', quantity: 2 },
  { sku: 'B', name: 'Banana', quantity: 5 },
  { sku: 'C', name: 'Cherry', quantity: 0 }
]);
assert.notStrictEqual(added, state);
for (let i = 0; i < state.length; i++) assert.notStrictEqual(added[i], state[i]);
assert.notStrictEqual(added[2], addedItem);

const restocked = applyInventoryCommand(state, Object.freeze({ type: 'RESTOCK', sku: 'A', amount: -2 }));
assert.deepEqual(restocked, [
  { sku: 'A', name: 'Apple', quantity: 0 },
  { sku: 'B', name: 'Banana', quantity: 5 }
]);
assert.notStrictEqual(restocked[1], state[1]);

const renamed = applyInventoryCommand(state, Object.freeze({ type: 'RENAME', sku: 'B', name: 'Berry' }));
assert.deepEqual(renamed, [
  { sku: 'A', name: 'Apple', quantity: 2 },
  { sku: 'B', name: 'Berry', quantity: 5 }
]);
const removed = applyInventoryCommand(state, Object.freeze({ type: 'REMOVE', sku: 'A' }));
assert.deepEqual(removed, [{ sku: 'B', name: 'Banana', quantity: 5 }]);
assert.notStrictEqual(removed[0], state[1]);

const found = findInventoryItem(state, 'B');
assert.deepEqual(found, { sku: 'B', name: 'Banana', quantity: 5 });
assert.notStrictEqual(found, state[1]);
assert.equal(findInventoryItem(state, 'missing'), null);
assert.equal(findInventoryItem([], 'A'), null);
assert.deepEqual(state, [
  { sku: 'A', name: 'Apple', quantity: 2 },
  { sku: 'B', name: 'Banana', quantity: 5 }
]);

assert.throws(() => applyInventoryCommand(state, { type: 'ADD', item: { sku: 'A', name: 'Again', quantity: 1 } }), RangeError);
assert.throws(() => applyInventoryCommand(state, { type: 'RESTOCK', sku: 'A', amount: -3 }), RangeError);
assert.throws(() => applyInventoryCommand(state, { type: 'RESTOCK', sku: 'Z', amount: 1 }), RangeError);
assert.throws(() => applyInventoryCommand(state, { type: 'RENAME', sku: 'Z', name: 'Zed' }), RangeError);
assert.throws(() => applyInventoryCommand(state, { type: 'REMOVE', sku: 'Z' }), RangeError);
assert.throws(() => applyInventoryCommand(state, { type: 'NOPE' }), RangeError);

for (const badState of [null, {}, [null], [{ sku: '', name: 'A', quantity: 0 }], [{ sku: 'A', name: '', quantity: 0 }], [{ sku: 'A', name: 'A', quantity: -1 }], [{ sku: 'A', name: 'A', quantity: 1.5 }]]) {
  assert.throws(() => findInventoryItem(badState, 'A'), TypeError);
}
for (const badCommand of [null, [], {}, { type: 1 }, { type: 'ADD', item: null }, { type: 'ADD', item: { sku: 'C', name: 'C', quantity: -1 } }, { type: 'RESTOCK', sku: 'A', amount: 0 }, { type: 'RESTOCK', sku: 'A', amount: 1.5 }, { type: 'RENAME', sku: 'A', name: '' }, { type: 'REMOVE', sku: '' }]) {
  assert.throws(() => applyInventoryCommand(state, badCommand), TypeError);
}
assert.throws(() => findInventoryItem(state, ''), TypeError);
assert.throws(() => findInventoryItem(state, 1), TypeError);

